/**
 * CPR Host Contract v0.1 (Continuous Production Readiness v1.1, §5.2).
 *
 * The surface a CPR host guarantees and a feature is allowed to depend on.
 * Versioned independently of any host application: a feature declares the
 * contract range it needs in its feature manifest, and the package engine
 * refuses an install that falls outside it.
 *
 * Rules this file exists to enforce:
 *  - a feature never reads process.env, never opens a pool, never names a role
 *  - a feature never owns identity; it resolves subjects through the host
 *  - nothing here has an implementation, so nothing can run on import
 *
 * Vendored from the cpr-starter reference host (@cpr/host-contract 0.1.0).
 */

export const HOST_CONTRACT_VERSION = '0.1.0' as const;

/* Identity ---------------------------------------------------------- */

/** Opaque, host-issued. Never parsed or constructed by a feature. */
export type SubjectId = string & { readonly __brand: 'SubjectId' };

/**
 * How a feature refers to a person it did not create. An audience row carries
 * one of these; the host decides what it points at (an employee, a patient, a
 * directory user). Features never dedupe or store their own person records.
 */
export interface SubjectRef {
  system: string;
  externalId: string;
}

export interface Subject {
  id: SubjectId;
  displayName: string;
  email?: string;
  phone?: string;
  /** Host-declared kind, e.g. 'employee' | 'patient'. Opaque to features. */
  kind: string;
}

export interface IdentityCapability {
  resolveSubject(ref: SubjectRef): Promise<Subject | null>;
  resolveMany(refs: SubjectRef[]): Promise<Map<string, Subject>>;
  currentSubject(): Promise<Subject | null>;
}

/* Auth -------------------------------------------------------------- */

/** e.g. 'outreach.connectors.manage'. Never a role name. */
export type PermissionName = string;

export interface CurrentUser {
  id: string;
  displayName: string;
  permissions: readonly PermissionName[];
}

export interface AuthCapability {
  currentUser(): Promise<CurrentUser | null>;
  has(permission: PermissionName): Promise<boolean>;
  requirePermission(permission: PermissionName): Promise<void>;
}

/* Data -------------------------------------------------------------- */

export interface QueryResult<T> {
  rows: T[];
  rowCount: number;
}

export interface DbCapability {
  query<T = unknown>(sql: string, params?: readonly unknown[]): Promise<QueryResult<T>>;
  transaction<T>(fn: (tx: DbCapability) => Promise<T>): Promise<T>;
}

/* Secrets and config ------------------------------------------------ */

/** Sentinel returned in place of a stored value. Plaintext never comes back. */
export const SECRET_PRESENT = '__secret_present__' as const;

export interface SecretsCapability {
  set(ref: string, value: string): Promise<void>;
  status(ref: string): Promise<typeof SECRET_PRESENT | null>;
  /** Uses the secret without exposing it — the host performs the call. */
  withSecret<T>(ref: string, fn: (value: string) => Promise<T>): Promise<T>;
}

export interface ConfigCapability {
  get(key: string): string | undefined;
  require(key: string): string;
}

/* Jobs -------------------------------------------------------------- */

export interface JobDefinition {
  id: string;
  /** Cron expression or an interval in milliseconds. */
  schedule: string | number;
  run(signal: AbortSignal): Promise<void>;
}

export interface JobsCapability {
  /**
   * The host owns scheduling and holds the singleton lock, so two running
   * slots cannot both fire the same job.
   */
  register(job: JobDefinition): void;
}

/* Outbound HTTP ----------------------------------------------------- */

export interface OutboundRequest {
  url: string;
  method?: string;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
}

export interface OutboundResponse {
  status: number;
  headers: Record<string, string>;
  text(): Promise<string>;
}

export interface OutboundCapability {
  /**
   * Enforces timeouts and the host's SSRF policy. A feature declares the hosts
   * it intends to reach in its manifest; anything else is refused.
   */
  fetch(req: OutboundRequest): Promise<OutboundResponse>;
}

/* Logging and audit ------------------------------------------------- */

export interface LogCapability {
  debug(message: string, fields?: Record<string, unknown>): void;
  info(message: string, fields?: Record<string, unknown>): void;
  warn(message: string, fields?: Record<string, unknown>): void;
  error(message: string, fields?: Record<string, unknown>): void;
}

export interface AuditEvent {
  action: string;
  subjectId?: SubjectId;
  target?: string;
  detail?: Record<string, unknown>;
}

export interface AuditCapability {
  record(event: AuditEvent): Promise<void>;
}

/* The host ---------------------------------------------------------- */

export interface Host {
  readonly contractVersion: typeof HOST_CONTRACT_VERSION;
  readonly auth: AuthCapability;
  readonly identity: IdentityCapability;
  readonly db: DbCapability;
  readonly secrets: SecretsCapability;
  readonly config: ConfigCapability;
  readonly jobs: JobsCapability;
  readonly outbound: OutboundCapability;
  readonly log: LogCapability;
  readonly audit: AuditCapability;
}

/**
 * CPR Host SDK (Continuous Production Readiness v1.1, §5.3).
 *
 * The seam a CPR feature imports. Interfaces and the registration shape only —
 * a feature consumes host capabilities through this module (or another
 * documented public contract) and never imports host implementation internals.
 *
 * Vendored from the cpr-starter reference host (@cpr/host-sdk 0.1.0). In the
 * published package this re-exports `@cpr/host-contract`; here it re-exports the
 * sibling module so a project carries one copy of the contract.
 */
import type { Host, PermissionName } from './host-contract.js';

export * from './host-contract.js';

/**
 * What a feature registers. The host calls `register` explicitly; importing a
 * feature module must have no effect of its own — no worker started, no route
 * mounted, no connection opened.
 */
export interface FeatureRegistration {
  routes?: (host: Host) => RouteHandlerMap;
  /** Declared, never invented at call time. The host maps them to its roles. */
  permissions?: readonly PermissionName[];
  navigation?: readonly NavigationEntry[];
  /** Called after routes are mounted. Start workers here, not on import. */
  start?: (host: Host) => Promise<void>;
  /** Must return once in-flight work has drained. */
  stop?: () => Promise<void>;
}

export interface NavigationEntry {
  id: string;
  label: string;
  path: string;
  /** Hidden unless the current user holds this. */
  requires?: PermissionName;
}

export type RouteHandlerMap = Record<string, unknown>;

/** Every feature's entry point has this shape. */
export type FeatureFactory = (host: Host) => FeatureRegistration;

export function assertContractVersion(host: Host, expected: string): void {
  if (host.contractVersion !== expected) {
    throw new Error(
      `Host contract mismatch: feature expects ${expected}, host provides ${host.contractVersion}`,
    );
  }
}

import { z } from 'zod';

/**
 * feature.manifest.json — what a CPR feature package declares about itself
 * (Continuous Production Readiness v1.1, §7 and Appendix B).
 *
 * The base is CPR Appendix B. Four groups of fields are carried over from the
 * v1 Outreach manifests, because they record WHY a decision was made and are
 * the part that stops the next person reversing it:
 *
 *   excludedDeliberately   a file left out on purpose, with the reason
 *   notableColumns         why a column exists (a delete that must not happen)
 *   install/uninstallActions   what an operator must do, including what NOT to drop
 *   portability            blockers and risks, stated rather than discovered
 *
 * Everything here is declaration. The package engine compares it against what
 * the package actually contains and refuses an install on a mismatch.
 *
 * Vendored from the cpr-starter reference host (@cpr/manifest-schema 0.1.0).
 */

export const SemverRange = z.string().min(1);

export const HostCapabilityUse = z.object({
  capability: z.enum([
    'auth', 'identity', 'db', 'secrets', 'config',
    'jobs', 'outbound', 'log', 'audit',
  ]),
  /** Why this feature needs it. A capability with no stated use is a smell. */
  reason: z.string().min(1),
});

export const PermissionDecl = z.object({
  /** Namespaced: <feature>.<area>.<verb>. Never a role name. */
  id: z.string().regex(/^[a-z0-9-]+(\.[a-z0-9-]+)+$/),
  grants: z.string().min(1),
  /** Where it came from, if the feature was ported. */
  previouslyMappedTo: z.string().optional(),
});

export const MigrationDecl = z.object({
  file: z.string().min(1),
  /** Namespaced per feature so two features cannot collide. */
  tables: z.array(z.string()).default([]),
  adoptsExisting: z.array(z.string()).default([]),
});

export const NotableColumn = z.object({
  column: z.string().min(1),
  why: z.string().min(1),
});

export const ExcludedFile = z.object({
  path: z.string().min(1),
  why: z.string().min(1),
});

export const JobDecl = z.object({
  id: z.string().min(1),
  schedule: z.string().min(1),
  /** False means the host must hold a singleton lock. */
  concurrencySafe: z.boolean(),
  note: z.string().optional(),
});

export const OutboundHostDecl = z.object({
  host: z.string().min(1),
  why: z.string().min(1),
});

export const Portability = z.object({
  blockers: z.array(z.string()).default([]),
  risks: z.array(z.string()).default([]),
});

export const FeatureManifest = z.object({
  manifestVersion: z.literal('1'),
  id: z.string().regex(/^[a-z0-9-]+$/),
  name: z.string().min(1),
  version: SemverRange,
  description: z.string().min(1),

  /** The contract range this feature runs against. */
  hostContract: SemverRange,

  entry: z.object({
    /** Module exporting a FeatureFactory. Nothing runs on import. */
    module: z.string().min(1),
    export: z.string().default('default'),
  }),

  hostCapabilities: z.array(HostCapabilityUse).default([]),
  permissions: z.array(PermissionDecl).default([]),
  featureDependencies: z.array(z.string()).default([]),

  database: z.object({
    migrations: z.array(MigrationDecl).default([]),
    notableColumns: z.array(NotableColumn).default([]),
  }).default({ migrations: [], notableColumns: [] }),

  jobs: z.array(JobDecl).default([]),
  outboundHosts: z.array(OutboundHostDecl).default([]),

  excludedDeliberately: z.array(ExcludedFile).default([]),
  installActions: z.array(z.string()).default([]),
  uninstallActions: z.array(z.string()).default([]),
  portability: Portability.default({ blockers: [], risks: [] }),

  compatibility: z.object({
    node: SemverRange,
    postgres: SemverRange.optional(),
  }),
});

export type FeatureManifest = z.infer<typeof FeatureManifest>;

export interface ValidationProblem {
  path: string;
  message: string;
}

/** Shape check only. The engine separately checks manifest against reality. */
export function validateManifest(
  input: unknown,
): { ok: true; manifest: FeatureManifest } | { ok: false; problems: ValidationProblem[] } {
  const r = FeatureManifest.safeParse(input);
  if (r.success) return { ok: true, manifest: r.data };
  return {
    ok: false,
    problems: r.error.issues.map((i) => ({
      path: i.path.join('.') || '(root)',
      message: i.message,
    })),
  };
}

/**
 * A job declared concurrencySafe: false must be matched by a host that can hold
 * a lock. Checked at install, not at first double-send.
 */
export function requiresJobLock(m: FeatureManifest): boolean {
  return m.jobs.some((j) => !j.concurrencySafe);
}

/**
 * The ONE seam between the CPR host adapter and the application it lives in.
 *
 * The reference host (cpr-starter) reached its pool and release id through
 * `../db.js` / `../config.js`. A Mock2 project already owns both — the scaffold's
 * `src/db/index.ts` exports the pg pool behind Drizzle and `src/config.ts` holds
 * the validated env — so the adapter takes them from here and nothing else in
 * `src/cpr/host/` needs editing when it is copied into a project.
 */
import { pool } from '../../db/index.js';
import { config } from '../../config.js';

export { pool };

/** Stamped into audit rows so an event can be tied to the release that wrote it. */
export const RELEASE_ID: string = (config as { RELEASE_ID?: string }).RELEASE_ID
  ?? process.env.RELEASE_ID
  ?? 'dev';

import type { DbCapability, QueryResult } from '../host-contract.js';
import { pool } from './deps.js';
import type pg from 'pg';

// Features get this, never the pool. They cannot reach .connect(), so they
// cannot hold a client open or start a transaction the host does not know about.
function wrap(exec: pg.Pool | pg.PoolClient): DbCapability {
  return {
    async query<T>(sql: string, params: readonly unknown[] = []): Promise<QueryResult<T>> {
      const r = await exec.query(sql, params as unknown[]);
      return { rows: r.rows as T[], rowCount: r.rowCount ?? 0 };
    },
    async transaction<T>(fn: (tx: DbCapability) => Promise<T>): Promise<T> {
      if ('release' in exec) return fn(wrap(exec)); // already inside one
      const client = await (exec as pg.Pool).connect();
      try {
        await client.query('BEGIN');
        const out = await fn(wrap(client));
        await client.query('COMMIT');
        return out;
      } catch (e) {
        await client.query('ROLLBACK');
        throw e;
      } finally {
        client.release();
      }
    },
  };
}

export const dbCapability: DbCapability = wrap(pool);

import type { ConfigCapability } from '../host-contract.js';

/**
 * Features read configuration here, never process.env. The prefix means a
 * feature can only see keys namespaced to it, so one feature cannot read
 * another's configuration or the host's secrets by guessing a name.
 */
export function makeConfig(feature: string): ConfigCapability {
  const prefix = feature.toUpperCase().replace(/-/g, '_') + '_';
  const raw = process.env;
  return {
    get(key: string): string | undefined {
      return raw[prefix + key.toUpperCase()];
    },
    require(key: string): string {
      const v = raw[prefix + key.toUpperCase()];
      if (v === undefined) throw new Error(`Missing configuration ${prefix}${key.toUpperCase()}`);
      return v;
    },
  };
}

import type { JobDefinition, JobsCapability } from '../host-contract.js';
import { pool } from './deps.js';
import { makeLog } from './log.js';

/**
 * Jobs run on the host's scheduler, under a Postgres advisory lock keyed on the
 * job id. Two running slots therefore cannot both fire the same job — the
 * failure the pre-CPR Outreach had with four bare intervals and no locking, and
 * the reason CPR §12.2 says job ownership is coordinated separately from the
 * web slots.
 *
 * register() only records. Nothing ticks until startJobs() is called, so
 * importing a feature never starts work.
 */

interface Registered extends JobDefinition {
  feature: string;
}

const registry: Registered[] = [];
const timers: NodeJS.Timeout[] = [];
let running = false;
const inFlight = new Set<Promise<void>>();

function lockKey(id: string): number {
  // Stable 31-bit hash. Advisory locks take a bigint; collisions only ever
  // serialise two jobs that would otherwise run in parallel — safe, not silent.
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) { h ^= id.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h & 0x7fffffff;
}

export function makeJobs(feature: string): JobsCapability {
  return {
    register(job: JobDefinition): void {
      if (running) throw new Error(`Job ${job.id} registered after start`);
      if (registry.some((j) => j.id === job.id)) throw new Error(`Duplicate job id ${job.id}`);
      registry.push({ ...job, feature });
    },
  };
}

async function runOnce(job: Registered, signal: AbortSignal): Promise<void> {
  const log = makeLog(job.feature);
  const key = lockKey(job.id);
  const client = await pool.connect();
  try {
    const { rows } = await client.query('SELECT pg_try_advisory_lock($1) AS got', [key]);
    if (!rows[0]?.got) { log.debug('job skipped, lock held elsewhere', { job: job.id }); return; }
    try {
      await job.run(signal);
      log.info('job completed', { job: job.id });
    } finally {
      await client.query('SELECT pg_advisory_unlock($1)', [key]);
    }
  } catch (e) {
    log.error('job failed', { job: job.id, error: e instanceof Error ? e.message : String(e) });
  } finally {
    client.release();
  }
}

export function startJobs(): void {
  running = true;
  for (const job of registry) {
    const ms = typeof job.schedule === 'number' ? job.schedule : NaN;
    if (!Number.isFinite(ms)) {
      // Cron is not implemented, and a cron string silently treated as an
      // interval would run at the wrong time forever. Refuse by name.
      makeLog(job.feature).error('job not scheduled: cron schedules are not supported yet', { job: job.id });
      continue;
    }
    const controller = new AbortController();
    const timer = setInterval(() => {
      const p = runOnce(job, controller.signal).finally(() => inFlight.delete(p));
      inFlight.add(p);
    }, ms);
    timers.push(timer);
  }
}

export async function stopJobs(): Promise<void> {
  for (const t of timers) clearInterval(t);
  timers.length = 0;
  await Promise.allSettled([...inFlight]);
  running = false;
}

export function registeredJobs(): { id: string; feature: string }[] {
  return registry.map((j) => ({ id: j.id, feature: j.feature }));
}

import { lookup } from 'node:dns/promises';
import net from 'node:net';
import type { OutboundCapability, OutboundRequest, OutboundResponse } from '../host-contract.js';

/**
 * Outbound HTTP with the two protections a feature must not be trusted to do
 * itself: a declared-host allowlist and an SSRF guard that resolves the name
 * before connecting (CPR §14).
 *
 * The allowlist comes from the feature's manifest, so a feature cannot widen
 * its own reach at runtime.
 */

function isPrivate(ip: string): boolean {
  if (net.isIPv4(ip)) {
    const [a, b] = ip.split('.').map(Number);
    return a === 10 || a === 127 || a === 0
      || (a === 172 && b >= 16 && b <= 31)
      || (a === 192 && b === 168)
      || (a === 169 && b === 254);
  }
  const v = ip.toLowerCase();
  return v === '::1' || v.startsWith('fc') || v.startsWith('fd') || v.startsWith('fe80');
}

export class OutboundRefused extends Error { code = 'OUTBOUND_REFUSED'; }

export function makeOutbound(feature: string, allowedHosts: readonly string[]): OutboundCapability {
  const allow = new Set(allowedHosts.map((h) => h.toLowerCase()));
  return {
    async fetch(req: OutboundRequest): Promise<OutboundResponse> {
      let url: URL;
      try { url = new URL(req.url); } catch { throw new OutboundRefused('Malformed URL'); }
      if (url.protocol !== 'https:' && url.protocol !== 'http:') {
        throw new OutboundRefused(`Refused scheme ${url.protocol}`);
      }
      if (!allow.has(url.hostname.toLowerCase())) {
        throw new OutboundRefused(
          `${feature} did not declare ${url.hostname} in outboundHosts`,
        );
      }
      // Resolve first. A declared name that resolves inward is still refused —
      // an allowlist alone does not stop DNS pointing at the control plane.
      const { address } = await lookup(url.hostname);
      if (isPrivate(address)) {
        throw new OutboundRefused(`${url.hostname} resolves to a private address`);
      }

      const ac = new AbortController();
      const timer = setTimeout(() => ac.abort(), req.timeoutMs ?? 10_000);
      try {
        const res = await globalThis.fetch(url, {
          method: req.method ?? 'GET',
          headers: req.headers,
          body: req.body,
          signal: ac.signal,
          redirect: 'manual', // a redirect can leave the allowlist
        });
        const headers: Record<string, string> = {};
        res.headers.forEach((v, k) => { headers[k] = v; });
        return { status: res.status, headers, text: () => res.text() };
      } finally {
        clearTimeout(timer);
      }
    },
  };
}

import type { LogCapability } from '../host-contract.js';

const REDACT = /^(password|secret|token|authorization|api[-_]?key|cookie)$/i;

function scrub(fields?: Record<string, unknown>): Record<string, unknown> {
  if (!fields) return {};
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(fields)) out[k] = REDACT.test(k) ? '[redacted]' : v;
  return out;
}

export function makeLog(feature: string): LogCapability {
  const emit = (level: string) => (message: string, fields?: Record<string, unknown>) => {
    // Structured JSON on stdout — the project logger, not ad hoc console output.
    // eslint-disable-next-line no-console
    console.log(JSON.stringify({ level, feature, message, ...scrub(fields), t: new Date().toISOString() }));
  };
  return { debug: emit('debug'), info: emit('info'), warn: emit('warn'), error: emit('error') };
}

import type { AuditCapability, AuditEvent } from '../host-contract.js';
import { pool, RELEASE_ID } from './deps.js';

// Rows land in platform_audit (migration cpr_platform.sql). The action is
// prefixed with the feature id so one table serves every feature without a
// feature being able to impersonate another.
export function makeAudit(feature: string): AuditCapability {
  return {
    async record(event: AuditEvent): Promise<void> {
      await pool.query(
        `INSERT INTO platform_audit (action, subject_id, target, detail, release_id)
         VALUES ($1, $2, $3, $4, $5)`,
        [
          `${feature}.${event.action}`,
          event.subjectId ?? null,
          event.target ?? null,
          JSON.stringify(event.detail ?? {}),
          RELEASE_ID,
        ],
      );
    },
  };
}

import type { AuthCapability, IdentityCapability, SecretsCapability } from '../host-contract.js';

/**
 * Capabilities the contract declares but this host does not implement yet.
 *
 * These throw. They do NOT return plausible values — no anonymous user, no
 * empty subject, no null secret. A feature that runs against a stubbed auth
 * appears to work and is not access-controlled; a campaign built on a stubbed
 * identity resolver messages the wrong people. Refusing by name is the only
 * safe shape for an unimplemented capability (and the Mock2 constitution's
 * "no silent simulation" rule says the same thing).
 *
 * In a Mock2 project the auth component already ships sessions, users and RBAC:
 * bind `auth` and `identity` to it (see the integration notes) and this file
 * shrinks to `secrets` alone.
 */

export class CapabilityNotBound extends Error {
  code = 'CAPABILITY_NOT_BOUND';
  constructor(capability: string, reason: string) {
    super(`Capability '${capability}' is not bound on this host: ${reason}`);
  }
}

const AUTH_REASON = 'bind AuthCapability to the project auth component (src/auth) before a feature uses it';
const IDENTITY_REASON = 'no subject source is configured; bind IdentityCapability to the project users table or directory';
const SECRETS_REASON = 'no credential vault is configured on this host';

export const unboundAuth: AuthCapability = {
  async currentUser() { throw new CapabilityNotBound('auth', AUTH_REASON); },
  async has() { throw new CapabilityNotBound('auth', AUTH_REASON); },
  async requirePermission() { throw new CapabilityNotBound('auth', AUTH_REASON); },
};

export const unboundIdentity: IdentityCapability = {
  async resolveSubject() { throw new CapabilityNotBound('identity', IDENTITY_REASON); },
  async resolveMany() { throw new CapabilityNotBound('identity', IDENTITY_REASON); },
  async currentSubject() { throw new CapabilityNotBound('identity', IDENTITY_REASON); },
};

export const unboundSecrets: SecretsCapability = {
  async set() { throw new CapabilityNotBound('secrets', SECRETS_REASON); },
  async status() { throw new CapabilityNotBound('secrets', SECRETS_REASON); },
  async withSecret() { throw new CapabilityNotBound('secrets', SECRETS_REASON); },
};

export const UNBOUND = ['auth', 'identity', 'secrets'] as const;
export const BOUND = ['db', 'config', 'jobs', 'outbound', 'log', 'audit'] as const;

import { HOST_CONTRACT_VERSION, type Host } from '../host-contract.js';
import { dbCapability } from './db.js';
import { makeLog } from './log.js';
import { makeAudit } from './audit.js';
import { makeJobs } from './jobs.js';
import { makeConfig } from './config.js';
import { makeOutbound } from './outbound.js';
import { unboundAuth, unboundIdentity, unboundSecrets } from './unbound.js';

/**
 * One Host object per feature. The feature identity is closed over, so audit
 * rows, log lines, config keys and the outbound allowlist are all scoped
 * without the feature being asked to identify itself honestly.
 */
export function hostFor(feature: string, outboundHosts: readonly string[] = []): Host {
  return {
    contractVersion: HOST_CONTRACT_VERSION,
    auth: unboundAuth,
    identity: unboundIdentity,
    secrets: unboundSecrets,
    db: dbCapability,
    config: makeConfig(feature),
    jobs: makeJobs(feature),
    outbound: makeOutbound(feature, outboundHosts),
    log: makeLog(feature),
    audit: makeAudit(feature),
  };
}

export { startJobs, stopJobs, registeredJobs } from './jobs.js';
export { CapabilityNotBound, BOUND, UNBOUND } from './unbound.js';

import { Router } from 'express';
import { HOST_CONTRACT_VERSION } from '../host-contract.js';
import { BOUND, UNBOUND, registeredJobs } from './index.js';
import { RELEASE_ID } from './deps.js';

/**
 * GET /platform/host — what this host actually implements (CPR §5.2, §11.1).
 * A feature's manifest declares which capabilities it needs; the package engine
 * compares that against this before install, so an unbound capability is
 * refused at install rather than at first call.
 *
 * Mount behind the app's auth middleware: the capability list is operational
 * detail, not public information.
 */
export const cprHostRouter = Router();

cprHostRouter.get('/platform/host', (_req, res) => {
  res.json({
    contractVersion: HOST_CONTRACT_VERSION,
    bound: BOUND,
    unbound: UNBOUND,
    jobs: registeredJobs(),
    release: RELEASE_ID,
  });
});

{
